 SELECT serial_id,sku_id,release_ref AS operation_id,from_epoch,state,target_warehouse_id FROM serial_release_intent
 WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND transfer_id=#{transfer}

 SELECT serial_id,sku_id,operation_id,from_epoch,state FROM serial_recovery_intent
 WHERE enterprise_id=#{e} AND warehouse_id=#{w} AND transfer_id=#{transfer} AND kind='TRANSFER'

AND serial_id IN #{sn}
